css:
/* ═══════════════════════════════════════════════════════
   EFRIS Sales Invoice — Beautiful Edition
   Palette:
     Navy   #1e3a5f   (headers, accents)
     Gold   #c9962a   (dividers, badges)
     Blue   #2980b9   (table head)
     Light  #eaf4fb   (alt rows, cards)
   ═══════════════════════════════════════════════════════ */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

* { box-sizing: border-box; }

.inv-wrap {
  font-family: 'Inter', Arial, sans-serif;
  font-size: 11px;
  color: #222;
  padding: 18px 22px;
  width: 100%;
  background: #fff;
}

/* ── HEADER ──────────────────────────────────────────────── */
.inv-header {
  display: flex;
  align-items: center;
  gap: 14px;
  padding-bottom: 10px;
}
.inv-header-left  { flex: 0 0 auto; }
.inv-header-center { flex: 1; }
.inv-header-right { flex: 0 0 auto; }

.inv-logo {
  max-height: 64px;
  max-width: 120px;
  display: block;
  float: none !important;
  margin: 0 !important;
}

.inv-company-name {
  font-size: 18px;
  font-weight: 700;
  color: #1e3a5f;
  text-transform: uppercase;
  letter-spacing: 1.2px;
  line-height: 1.2;
}
.inv-company-sub {
  font-size: 10px;
  color: #555;
  margin-top: 2px;
  line-height: 1.5;
}
.inv-company-tin {
  margin-top: 3px;
  font-size: 10px;
  font-weight: 600;
  color: #1e3a5f;
}

.inv-badge {
  background: #1e3a5f;
  color: #fff;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-align: center;
  line-height: 1.3;
  padding: 10px 16px;
  border-radius: 6px;
  text-transform: uppercase;
  border-bottom: 3px solid #c9962a;
}

/* ── GOLD DIVIDER ────────────────────────────────────────── */
.inv-divider {
  height: 3px;
  background: linear-gradient(to right, #1e3a5f, #c9962a, #1e3a5f);
  border-radius: 2px;
  margin: 6px 0 10px;
}

/* ── META ROW ────────────────────────────────────────────── */
.inv-meta-row {
  display: flex;
  gap: 0;
  background: #1e3a5f;
  border-radius: 6px;
  overflow: hidden;
}
.inv-meta-block {
  flex: 1;
  padding: 7px 12px;
  border-right: 1px solid rgba(255,255,255,0.15);
}
.inv-meta-block:last-child { border-right: none; }
.inv-meta-label {
  display: block;
  font-size: 9px;
  font-weight: 500;
  color: #c9962a;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  margin-bottom: 2px;
}
.inv-meta-value {
  display: block;
  font-size: 11px;
  font-weight: 600;
  color: #fff;
}

/* ── TWO COLUMN ──────────────────────────────────────────── */
.inv-two-col {
  display: flex;
  gap: 10px;
}

.inv-card {
  flex: 1;
  border: 1px solid #d0dce8;
  border-radius: 6px;
  overflow: hidden;
  margin-bottom: 10px;
}
.inv-bill-card {
  border-left: 3px solid #c9962a;
}
.inv-card-title {
  background: #eaf4fb;
  color: #1e3a5f;
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 5px 10px;
  border-bottom: 1px solid #d0dce8;
}
.inv-card-body {
  padding: 8px 10px;
  font-size: 10.5px;
  line-height: 1.7;
  color: #333;
}
.inv-cust-name {
  font-size: 12px;
  font-weight: 700;
  color: #1e3a5f;
  margin-bottom: 3px;
}
.lbl {
  font-weight: 600;
  color: #555;
}

/* ── ITEMS TABLE ─────────────────────────────────────────── */
.inv-table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 4px;
  font-size: 10px;
}
.inv-table thead tr {
  background: #1e3a5f;
  color: #fff;
}
.inv-table thead th {
  padding: 7px 8px;
  font-weight: 600;
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  text-align: left;
  border: none;
}
.inv-table tbody tr {
  border-bottom: 1px solid #e8edf2;
}
.row-odd  { background: #fff; }
.row-even { background: #f5f9fd; }
.inv-table tbody td {
  padding: 6px 8px;
  vertical-align: top;
  color: #333;
}
.item-name  { font-weight: 600; color: #1e3a5f; }
.item-desc  { font-size: 9px; color: #666; }
.item-batch { font-size: 9px; color: #888; }
.item-code  { font-size: 9.5px; color: #555; }
.tc { text-align: center; }
.tr { text-align: right; }

/* ── TOTALS BOX ──────────────────────────────────────────── */
.inv-totals-wrap {
  display: flex;
  justify-content: flex-end;
  margin-top: 6px;
}
.inv-totals {
  border-collapse: collapse;
  min-width: 280px;
  border: 1px solid #d0dce8;
  border-radius: 6px;
  overflow: hidden;
}
.inv-totals tr { border-bottom: 1px solid #e8edf2; }
.inv-totals tr:last-child { border-bottom: none; }
.tot-lbl {
  padding: 5px 14px;
  font-size: 10px;
  color: #555;
  text-align: left;
  background: #f5f9fd;
}
.tot-val {
  padding: 5px 14px;
  font-size: 10px;
  font-weight: 600;
  color: #1e3a5f;
  text-align: right;
  background: #f5f9fd;
}
.tot-grand {
  background: #1e3a5f !important;
}
.tot-grand td {
  padding: 8px 14px;
  font-size: 12px;
  font-weight: 700;
  color: #fff !important;
  text-align: right;
  background: #1e3a5f !important;
}
.tot-grand td:first-child { text-align: left; }

/* ── IN WORDS ────────────────────────────────────────────── */
.inv-words {
  margin: 12px 0 10px;
  padding: 8px 12px;
  background: #f5f9fd;
  border-left: 3px solid #c9962a;
  border-radius: 0 4px 4px 0;
  font-size: 10.5px;
  color: #333;
  font-style: italic;
}
.inv-words-label {
  font-style: normal;
  font-weight: 700;
  color: #1e3a5f;
  margin-right: 4px;
}

/* ── FOOTER ROW ──────────────────────────────────────────── */
.inv-footer-row {
  display: flex;
  gap: 10px;
  margin-top: 10px;
  padding-top: 10px;
  border-top: 1px dashed #ccc;
}
.inv-footer-block {
  flex: 1;
  font-size: 10px;
}
.inv-footer-title {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: #1e3a5f;
  margin-bottom: 4px;
}
.inv-footer-value { color: #333; line-height: 1.6; }
.inv-sig-line {
  border-bottom: 1px solid #1e3a5f;
  width: 120px;
  margin: 18px 0 3px;
}
.inv-sig-hint { font-size: 8.5px; color: #888; }
.inv-footer-note-block { text-align: right; }
.inv-footer-note {
  font-size: 9px;
  color: #777;
  font-style: italic;
  line-height: 1.7;
  margin-top: 6px;
}

/* ══════════════════════════════════════════════════════════
   EFRIS / URA KAKASA SECTION
   ══════════════════════════════════════════════════════════ */
.efris-wrap {
  margin-top: 14px;
  border: 1.5px solid #1e3a5f;
  border-radius: 7px;
  overflow: hidden;
  page-break-inside: avoid;
}

.efris-header-bar {
  display: flex;
  align-items: center;
  background: #1e3a5f;
  padding: 6px 14px;
  gap: 10px;
}
.efris-header-line {
  flex: 1;
  height: 1px;
  background: rgba(201,150,42,0.6);
}
.efris-header-text {
  font-size: 11px;
  font-weight: 700;
  color: #c9962a;
  letter-spacing: 2px;
  text-transform: uppercase;
  white-space: nowrap;
}

.efris-body {
  display: flex;
  align-items: center;
  padding: 10px 16px;
  gap: 16px;
  background: #f8fbff;
}

.efris-logo-col {
  flex: 0 0 auto;
  width: 64px;
  text-align: center;
}
.efris-ura-img {
  float: none !important;
  width: 60px;
  height: auto;
  margin: 0 !important;
  display: block;
}

.efris-fields-col {
  flex: 1;
  font-size: 10.5px;
}
.efris-field-row {
  display: flex;
  align-items: baseline;
  gap: 6px;
  padding: 2.5px 0;
  border-bottom: 1px dotted #d0dce8;
}
.efris-field-row:last-child { border-bottom: none; }
.efris-field-lbl {
  font-weight: 600;
  color: #1e3a5f;
  min-width: 135px;
  font-size: 10px;
}
.efris-field-sep { color: #999; }
.efris-field-val {
  font-size: 10.5px;
  color: #222;
  word-break: break-all;
  font-family: 'Courier New', monospace;
}

.efris-qr-col {
  flex: 0 0 auto;
  text-align: center;
}
.efris-qr-img {
  float: none !important;
  width: 96px;
  height: 96px;
  margin: 0 !important;
  display: block;
  border: 2px solid #1e3a5f;
  border-radius: 4px;
  padding: 2px;
  background: #fff;
}
.efris-qr-hint {
  font-size: 8px;
  color: #888;
  margin-top: 3px;
  text-align: center;
}

.efris-footer-msg {
  background: #eaf4fb;
  border-top: 1px solid #c9ddf0;
  padding: 5px 16px;
  font-size: 9.5px;
  color: #1e3a5f;
  text-align: center;
}
